#[test]
fn classification_parser_matches_the_original() {
    for &(s, v) in CLASS {
        assert_eq!(parse_classification(s), v, "{s:?}");
    }
}

#[test]
fn movement_parser_matches_the_original() {
    for &(s, v) in MOVE {
        assert_eq!(parse_movement(s), v, "{s:?}");
    }
}

#[test]
fn target_flag_parser_matches_the_original() {
    for &(s, v) in TARGS {
        assert_eq!(parse_target_flags(s), v, "{s:?}");
    }
}

#[test]
fn weapon_kind_parser_matches_the_original() {
    for &(s, v) in KIND {
        assert_eq!(parse_weapon_kind(s), v, "{s:?}");
    }
}
